const TABLES = Object.freeze({
  2025: Object.freeze({
    standardDeductionCents: 2_410_00,
    personalCreditCents: 29_00,
    midrangeBelowCents: 100_001_00,
    brackets: BRACKETS_2025,
    sources: Object.freeze([
      "Arkansas DFA, Withholding Tax Formula Method, effective 01/01/2025 (Tax Year 2025): https://www.dfa.arkansas.gov/wp-content/uploads/whformula_2024_1.pdf",
    ]),
  }),
  2026: Object.freeze({
    standardDeductionCents: 2_470_00,
    personalCreditCents: 29_00,
    midrangeBelowCents: 100_001_00,
    brackets: BRACKETS,
    sources: Object.freeze([
      "Arkansas DFA, Withholding Tax Formula Method (effective 01/01/2026): https://www.dfa.arkansas.gov/wp-content/uploads/Withholding-Tax-Formula.pdf",
      "Arkansas DFA, Withholding Tax Instructions for Employers (2026): https://www.dfa.arkansas.gov/wp-content/uploads/withholdInstructions_2026.pdf",
      "Arkansas DFA, AR4EC Employee's Withholding Exemption Certificate (2026): https://www.dfa.arkansas.gov/wp-content/uploads/AR4EC2026.pdf",
    ]),
  }),
});

function validateForm(form) {
  if (!onFile(form)) return;
  const c = formChecker("Arkansas AR4EC");
  c.nonNegInt(form, "exemptions");
  c.cents(form, "additionalWithholdingCents");
  if (c.bool(form, "lowIncome")) {
    c.fail("the low-income tax rate tables (line 5) aren't sourced here yet; withhold by hand and review");
  }
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form }) {
  const t = TABLES[taxYear];
  validateForm(form);
  const has = onFile(form);
  const annual = wagesCents * payPeriodsPerYear;
  const netDollars = Math.max(0, Math.floor((annual - t.standardDeductionCents) / 100));
  // $50 midrange: $23,054 -> $23,050 (the middle of $23,000-$23,100).
  const income = netDollars * 100 < t.midrangeBelowCents ? (Math.floor(netDollars / 100) * 100 + 50) * 100 : netDollars * 100;
  let row = t.brackets[0];
  for (const r of t.brackets) if (income >= r[0]) row = r;
  const [, rateBp, adjustment] = row;
  const gross = Math.max(0, Math.round(((income * rateBp) / 10_000 - adjustment) / 100) * 100);
  const credits = (has ? form.exemptions ?? 0 : 0) * t.personalCreditCents;
  const net = Math.max(0, gross - credits);
  const extra = has ? form.additionalWithholdingCents ?? 0 : 0;
  return {
    stateCents: Math.round(net / payPeriodsPerYear) + extra,
    formBasis: has ? "ar4ec" : "none-on-file-no-exemptions",
    lines: { incomeCents: income, grossTaxCents: gross, creditsCents: credits, netTaxCents: net },
  };
}

module.exports = {
  code: "AR",
  name: "Arkansas",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
